begin;
create extension if not exists pgtap with schema extensions;
select plan(19);
insert into auth.users(id,email) values('93000000-0000-0000-0000-000000000001','operations-dispatcher@example.test');
update public.profiles set active=true,role='DISPATCHER' where id='93000000-0000-0000-0000-000000000001';
select set_config('test.request',(select id::text from public.moving_requests where request_number='LM-001004'),true);
select set_config('test.move',(select id::text from public.moves where request_id=current_setting('test.request')::uuid),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','93000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.request_action(current_setting('test.request')::uuid,(select version from public.moving_requests where id=current_setting('test.request')::uuid),'cancel','')$$,'Dispatcher cancels without reason');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'CANCELLED','Request cancelled');
select is((select status from public.moves where id=current_setting('test.move')::uuid),'CANCELLED','Move cancelled atomically');
select is((select status from public.quotes where request_id=current_setting('test.request')::uuid),'CANCELLED','Quote suspended');
select throws_ok($$select public.request_action(current_setting('test.request')::uuid,1,'reactivate','')$$,'P0001','CONFLICT','Stale update rejected');
select lives_ok($$select public.request_action(current_setting('test.request')::uuid,(select version from public.moving_requests where id=current_setting('test.request')::uuid),'reactivate','')$$,'Dispatcher reactivates for review');
select is((select status from public.moves where id=current_setting('test.move')::uuid),'PENDING_REVIEW','Original Move reused for review');
select is((select status from public.moving_requests where id=current_setting('test.request')::uuid),'PENDING_REVIEW','Request requires review');
select set_config('test.note',public.save_note(current_setting('test.request')::uuid,'Internal fixture note')::text,true);
select lives_ok($$select public.save_note(current_setting('test.request')::uuid,'Edited note',current_setting('test.note')::uuid)$$,'Staff edits a note');
select lives_ok($$select public.save_note(current_setting('test.request')::uuid,'',current_setting('test.note')::uuid,true)$$,'Staff deletes a note');
select throws_ok($$select public.edit_customer('10000000-0000-0000-0000-000000000001',1,'Cliente 1','Ejemplo','+14165550101','')$$,'23514',null,'Direct RPC rejects Canadian NANP phone');
select lives_ok($$select public.edit_customer('10000000-0000-0000-0000-000000000001',1,'Cliente 1','Ejemplo','+13055550101','')$$,'Optional email can be cleared');
select ok((select email is null from public.customers where id='10000000-0000-0000-0000-000000000001'),'Empty email stored as null');
select ok((public.dashboard_metrics()->>'new_requests')::integer=(select count(*) from public.moving_requests where status='NEW'),'Dashboard metric counts actual requests');
reset role;
select set_config('test.pending',public.dashboard_metrics()->>'quotes_pending',true);
update public.quotes set status='ACCEPTED' where request_id=current_setting('test.request')::uuid;
insert into public.quote_communications(quote_id,terms_version,terms,medium,communicated_at,actor_id)
select id,terms_version,'{}','PHONE',now(),'93000000-0000-0000-0000-000000000001' from public.quotes where request_id=current_setting('test.request')::uuid;
select is((public.dashboard_metrics()->>'quotes_pending')::integer,current_setting('test.pending')::integer+1,'Current communicated terms count as pending');
insert into public.quote_communications(quote_id,terms_version,terms,medium,communicated_at,actor_id)
select id,terms_version,'{}','WHATSAPP',now(),'93000000-0000-0000-0000-000000000001' from public.quotes where request_id=current_setting('test.request')::uuid;
select is((public.dashboard_metrics()->>'quotes_pending')::integer,current_setting('test.pending')::integer+1,'Repeated communications do not multiply metric');
update public.quotes set terms_version=terms_version+1 where request_id=current_setting('test.request')::uuid;
select is((public.dashboard_metrics()->>'quotes_pending')::integer,current_setting('test.pending')::integer,'Old communicated version does not count');
update public.quotes set status='CONFIRMED' where request_id=current_setting('test.request')::uuid;
select is((public.dashboard_metrics()->>'quotes_pending')::integer,current_setting('test.pending')::integer,'Confirmed quote is excluded');
update public.profiles set active=false where id='93000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.dashboard_metrics()$$,'42501',null,'Unauthorized metrics fail rather than show fake zero counts');
reset role;
select * from finish();
rollback;
